files.language/class_shadowing_builtin.wren:
// Defining a class with same name as a built-in produces a compile error
// "Module variable is already defined."
// expect error line 4: Module variable is already defined.
class List {
  static name { "custom List" }
}

// nontest
var Module = "from module"
System.print("ran module")

